INSERT INTO email_backfill_jobs (id, link_id, fusionauth_user_id, threads_requested_limit, status, is_recovery) VALUES ($1, $2, $3, $4, 'Init', $5) ON CONFLICT (link_id) WHERE status IN ('Init', 'InProgress') DO NOTHING RETURNING id, link_id, fusionauth_user_id, threads_requested_limit, total_threads, threads_retrieved_count, status as "status: db::backfill::BackfillJobStatus", created_at, updated_at
